{
    int kram_mein_hai = 1; // array kram mein hai ya nahi
    int i;

    for (i = 0; i < n - 1; i = i + 1)
    {
        if (a[i] > a[i + 1])
        {
            kram_mein_hai = 0; // yahan galti mili
